'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let library=[],visible=[],limit=30;
const el=id=>document.getElementById(id),labels={russian:'Русская',european:'Европейская',asian:'Азиатская'};
function draw(reset=true){if(reset)limit=30;const words=el('search').value.trim().toLocaleLowerCase('ru').split(/\s+/),cuisine=el('cuisine').value,meal=el('meal').value;visible=library.filter(r=>(!cuisine||r.cuisines.includes(cuisine))&&(!meal||r.categories.includes(meal))&&(!el('instructions-only').checked||r.hasInstructions)&&words.every(w=>(r.name+' '+r.ingredientText).toLocaleLowerCase('ru').includes(w)));el('status').textContent='Найдено '+visible.length+' из '+library.length;el('random').disabled=!visible.length;el('more').hidden=limit>=visible.length;el('cards').innerHTML=visible.slice(0,limit).map(r=>`<article class="card"><h2>${esc(r.name)}</h2><p>${esc(r.cuisines.map(c=>labels[c]).join(' · ')||'Кухня не указана')}</p><p>${r.hasInstructions?'Есть раздел приготовления':'Текст и сведения о блюде'}</p><small>Викиучебник · оригинальный текст</small><button data-id="${esc(r.id)}">Открыть рецепт →</button></article>`).join('')||'<p>Рецепты не найдены. Попробуйте убрать один из фильтров.</p>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetails(library.find(r=>r.id===b.dataset.id)))}
function renderText(text){return text.split(/\n\s*\n/).map(p=>'<p class="original-text">'+esc(p)+'</p>').join('')}
function openDetails(r){el('detail-content').innerHTML=`<p class="detail-note">КУЛИНАРНАЯ КНИГА</p><h2>${esc(r.name)}</h2>${r.blocks.map(b=>`<section class="original-section"><h3>${esc(b.heading)}</h3>${renderText(b.text)}</section>`).join('')}<details class="attribution"><summary>Источник, авторы и лицензия</summary><p>Рецепт взят из русского Викиучебника. Авторы: участники Викиучебника, перечисленные в истории страницы.</p><p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Исходная редакция</a> · <a href="${esc(r.historyUrl)}" target="_blank" rel="noopener noreferrer">История и авторы</a></p><p><a href="${esc(r.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(r.license)}</a>. Текст доступен на условиях этой лицензии.</p><p>${esc(r.formatNote)}</p><p>Редакция: ${esc(new Date(r.sourceUpdatedAt).toLocaleDateString('ru-RU'))}</p></details>`;el('detail').showModal()}
for(const id of ['search','cuisine','meal','instructions-only'])el(id).addEventListener(id==='search'?'input':'change',()=>draw());el('more').onclick=()=>{limit+=30;draw(false)};el('random').onclick=()=>{if(visible.length)openDetails(visible[Math.floor(Math.random()*visible.length)])};document.querySelector('.close').onclick=()=>el('detail').close();
(async()=>{try{let data;try{const res=await fetch('/api/recipes');if(!res.ok)throw Error('api');data=await res.json();if(data.version!==2)throw Error('version')}catch{const res=await fetch('wiki-recipes.json');if(!res.ok)throw Error('snapshot');data=await res.json()}library=data.recipes;draw()}catch{el('status').textContent='Не удалось загрузить книгу. Обновите страницу.'}})();
